from common import *
notch='clip-path:polygon(0 14px,14px 14px,14px 0,calc(100% - 14px) 0,calc(100% - 14px) 14px,100% 14px,100% calc(100% - 14px),calc(100% - 14px) calc(100% - 14px),calc(100% - 14px) 100%,14px 100%,14px calc(100% - 14px),0 calc(100% - 14px))'
def card(code,name,deco,style=''):
    return f'<div class="t l" style="height:230px;background:var(--surface)"><div style="position:absolute;left:50%;top:44%;transform:translate(-50%,-50%);width:270px;height:176px;background:var(--surface-warm);{notch};{style}">{deco}<div style="position:absolute;left:30px;right:30px;top:30px"><p class="eyebrow" style="margin:0 0 6px">Plate</p><h3 class="display-s" style="margin:0;text-transform:uppercase">Built to be used</h3>__X__<p class="body" style="font-size:13px;line-height:1.5;margin:10px 0 0">Honest materials, no tricks.</p></div></div>{lab(code,name)}</div>'
E1=card('E1','Korte rode bies onder de kop','','').replace('__X__','<div style="width:56px;height:4px;background:var(--action);margin-top:10px"></div>')
E2=card('E2','Rode bies langs de bovenrand','<div style="position:absolute;left:14px;right:14px;top:0;height:7px;background:var(--action)"></div>').replace('__X__','')
E3=card('E3','Trainingsstrepen links','<div style="position:absolute;left:0;top:14px;bottom:14px;width:6px;background:var(--action)"></div><div style="position:absolute;left:12px;top:14px;bottom:14px;width:6px;background:var(--surface)"></div>').replace('__X__','').replace('left:30px;right:30px;top:30px','left:48px;right:24px;top:30px')
E4=card('E4','Stiksel: gestippelde naad','<div style="position:absolute;inset:22px;border:2px dashed var(--ink);opacity:.6"></div>').replace('__X__','').replace('left:30px;right:30px;top:30px','left:42px;right:42px;top:40px')
E5=card('E5','Dubbele bies (rood + wit)','<div style="position:absolute;left:14px;right:14px;top:0;height:5px;background:var(--action)"></div><div style="position:absolute;left:14px;right:14px;top:8px;height:3px;background:var(--surface)"></div>').replace('__X__','')
E6=card('E6','Rode bies als hoekmarkering','<div style="position:absolute;left:14px;top:0;width:60px;height:7px;background:var(--action)"></div><div style="position:absolute;right:14px;bottom:0;width:60px;height:7px;background:var(--action)"></div>').replace('__X__','')
body=f'''<h2>E · Bies, strepen en naad</h2><p class="note">Een klein rood detail als op het echte product: geweven bies langs een doel, strepen van een trainingspak, een stikselnaad. De naam "Golden Goal" is geschrapt; dit is puur een detail. Eén kiezen.</p>
<div class="g">{E1}{E2}{E3}{E4}{E5}{E6}</div>'''
write('Piping','Analoog: keuzes',720,body,'Optie-galerij E: rode details op kaarten: korte bies onder een kop, bies langs de bovenrand, trainingsstrepen, gestippelde stikselnaad, dubbele bies, hoekmarkeringen. Rood is `action`; blijf bij één detail per kaart en één soort per site.\n')
